Method.Source:
    /// <summary>
    /// Runs when datasouce record is activted.
    /// </summary>
    /// <returns>Is active.</returns>
    public int active()
    {
        int ret = next active();

        this.metEnableDatasourceFields();

        return ret;
    }

    /// <summary>
    /// CB756_ValidationOfABNToATOSystem.
    /// Enables and disables datasource <c>TaxRegistration</c> fields.
    /// </summary>
    private void metEnableDatasourceFields()
    {
        TaxVATNumTable  taxVATNumTable;
        boolean         isVerifiedDateEmpty;

        taxVATNumTable = this.cursor();
        isVerifiedDateEmpty = (taxVATNumTable.METVerifiedDate == dateNull());

        this.object(fieldNum(TaxVATNumTable, Name)).allowEdit(isVerifiedDateEmpty);
        this.object(fieldNum(TaxVATNumTable, METEntityType)).allowEdit(isVerifiedDateEmpty);
        this.object(fieldNum(TaxVATNumTable, METStatus)).allowEdit(isVerifiedDateEmpty);

        this.object(fieldNum(TaxVATNumTable, METVerifiedDate)).allowEdit(false);
    }
